/* Piglet Web Flasher — Main JS */
(function () {
  "use strict";

  // Show browser warning if Web Serial is not available
  if (!("serial" in navigator)) {
    var warn = document.getElementById("browserWarn");
    if (warn) warn.style.display = "block";
  }

  // Load build version from version.json (generated by CI)
  fetch("version.json", { cache: "no-store" })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (v) {
      if (v && v.build) {
        var el = document.getElementById("build");
        if (el) el.textContent = v.build;
      }
    })
    .catch(function () { /* version.json not available yet */ });
})();
